using System;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.Tilemaps;namespace Rootborn.Tests.EditMode.Interiors{public class PlacedFurnitureDepthPresentationTests{
GameObject grid;Tilemap map;Component presenter;Tile tile;Texture2D texture;Sprite sprite;
void Call(string name){presenter.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(presenter,null);}
[SetUp]public void Setup(){var type=typeof(Rootborn.UI.Interiors.AuthoredHousePlacementBinding).Assembly.GetType("Rootborn.UI.Interiors.PlacedFurnitureDepthPresentation");Assert.That(type,Is.Not.Null,"Placed furniture needs independent floor-depth presentation");grid=new GameObject("Grid",typeof(Grid));var go=new GameObject("Source",typeof(Tilemap),typeof(TilemapRenderer));go.transform.SetParent(grid.transform,false);map=go.GetComponent<Tilemap>();map.GetComponent<TilemapRenderer>().sortingOrder=10000;texture=new Texture2D(48,96);sprite=Sprite.Create(texture,new Rect(0,0,48,96),new Vector2(.5f,.25f),48);tile=ScriptableObject.CreateInstance<Tile>();tile.sprite=sprite;tile.colliderType=Tile.ColliderType.None;presenter=go.AddComponent(type);Call("OnEnable");}
[TearDown]public void Cleanup(){if(presenter!=null)Call("OnDisable");if(grid!=null)UnityEngine.Object.DestroyImmediate(grid);if(tile!=null)UnityEngine.Object.DestroyImmediate(tile);if(sprite!=null)UnityEngine.Object.DestroyImmediate(sprite);if(texture!=null)UnityEngine.Object.DestroyImmediate(texture);}
SpriteRenderer[] Views=>map.GetComponentsInChildren<SpriteRenderer>(true);
[Test]public void OppositeFloorRowsUseIndependentOrdersAroundPlayer(){map.SetTile(new Vector3Int(0,-2,0),tile);map.SetTile(new Vector3Int(0,2,0),tile);Call("RefreshPresentation");Assert.That(Views.Length,Is.EqualTo(2));Assert.That(Views.Select(v=>v.sortingOrder),Is.EquivalentTo(new[]{10072,9880}));Assert.That(map.GetComponent<TilemapRenderer>().enabled,Is.False);}
[Test]public void SpriteUsesTileAnchorWorldPositionWithoutChangingLogicalTile(){map.transform.localPosition=new Vector3(3,4,0);var c=new Vector3Int(2,-3,0);map.SetTile(c,tile);Call("RefreshPresentation");Assert.That(Views.Single().transform.position,Is.EqualTo(map.GetCellCenterWorld(c)));Assert.That(Views.Single().sprite,Is.SameAs(sprite));Assert.That(map.GetTile(c),Is.SameAs(tile));Assert.That(map.GetComponentsInChildren<Collider2D>(true),Is.Empty);}
[Test]public void CellTintAndTransformReachVisualAndDepth(){var c=Vector3Int.zero;map.SetTile(c,tile);map.SetTileFlags(c,TileFlags.None);map.SetColor(c,Color.red);map.SetTransformMatrix(c,Matrix4x4.TRS(new Vector3(.25f,0,0),Quaternion.identity,new Vector3(2,1,1)));Call("RefreshPresentation");var v=Views.Single();Assert.That(v.color,Is.EqualTo(Color.red));Assert.That(v.transform.localScale,Is.EqualTo(new Vector3(2,1,1)));Assert.That(v.transform.position.x,Is.EqualTo(.75f).Within(.001));Assert.That(v.sortingOrder,Is.EqualTo(9976));}
[Test]public void MoveReplaceAndRemoveLeaveNoStaleOrDuplicateViews(){map.SetTile(Vector3Int.zero,tile);Call("RefreshPresentation");map.SetTile(Vector3Int.zero,null);map.SetTile(Vector3Int.right,tile);Call("RefreshPresentation");Call("RefreshPresentation");Assert.That(Views.Length,Is.EqualTo(1));Assert.That(Views.Single().transform.position,Is.EqualTo(map.GetCellCenterWorld(Vector3Int.right)));map.ClearAllTiles();Call("RefreshPresentation");Assert.That(Views,Is.Empty);}
[Test]public void DisabledPresenterRestoresOriginalRendererAndHidesItsViews(){map.SetTile(Vector3Int.zero,tile);Call("RefreshPresentation");Call("OnDisable");Assert.That(map.GetComponent<TilemapRenderer>().enabled,Is.True);Assert.That(Views.All(v=>!v.enabled),Is.True);Assert.That(map.HasTile(Vector3Int.zero),Is.True);}
}}
